import os
import shutil
import core.models
from django.db import migrations, models
from django.conf import settings


def migrate_existing_datasets(apps, schema_editor):
    """
    Migrate existing dataset files from flat structure to hierarchical structure.
    Old: assignment_datasets/filename.csv
    New: assignment_datasets/<org>/<course>/<period>/<assignment>/filename.csv
    """
    AssignmentDataSet = apps.get_model('core', 'AssignmentDataSet')
    
    for dataset in AssignmentDataSet.objects.all():
        if not dataset.file:
            continue
            
        old_path = dataset.file.path
        
        # Skip if file doesn't exist
        if not os.path.exists(old_path):
            continue
            
        # Get the filename from the old path
        filename = os.path.basename(old_path)
        
        # Check if already in hierarchical structure (has subdirectories)
        relative_path = dataset.file.name
        if relative_path.count('/') > 1:  # More than just 'assignment_datasets/'
            # Already migrated, skip
            continue
        
        # Generate new hierarchical path
        assignment = dataset.assignment
        course = assignment.course
        org = course.organization
        
        # Sanitize path components
        org_safe = org.shortname.replace(' ', '_')
        course_safe = course.name.replace(' ', '_')
        period_safe = course.period.replace(' ', '_')
        assignment_safe = assignment.name.replace(' ', '_')
        
        new_relative_path = f'assignment_datasets/{org_safe}/{course_safe}/{period_safe}/{assignment_safe}/{filename}'
        new_path = os.path.join(settings.MEDIA_ROOT, new_relative_path)
        
        # Create directory structure
        os.makedirs(os.path.dirname(new_path), exist_ok=True)
        
        # Move the file
        try:
            shutil.move(old_path, new_path)
            # Update the database record
            dataset.file.name = new_relative_path
            dataset.save(update_fields=['file'])
            print(f"Migrated {old_path} -> {new_path}")
        except Exception as e:
            print(f"Error migrating {old_path}: {e}")


def reverse_migrate_datasets(apps, schema_editor):
    """
    Reverse migration: move files back to flat structure.
    """
    AssignmentDataSet = apps.get_model('core', 'AssignmentDataSet')
    
